<script setup lang="ts">
import { computed, ref } from 'vue'
import { NoratoSidebar, type NoratoSidebarSection } from '@norato/vue'
import PlaygroundSelect from './PlaygroundSelect.vue'
const props = defineProps<{ copiedKey: string }>()
const emit = defineEmits<{ copy: [key: string, value: string] }>()
const collapsed = ref(false), disabled = ref(false), variant = ref<'glass'|'bar'>('glass'), activeHref = ref('/overview'), activations = ref(0)
const sections = computed<NoratoSidebarSection[]>(() => [{ label: 'فضای کاری', items: [{ label: 'نمای کلی', href: '/overview', icon: '⌂' }, { label: 'پروژه‌ها', href: '/projects', icon: '▦', count: 3, children: [{ label: 'فعال', href: '/projects/active' }, { label: 'بایگانی', href: '/projects/archive' }] }, { label: 'گزارش‌ها', href: '/reports', icon: '▤' }, { label: 'تنظیمات', icon: '⚙', disabled: true }] }])
const snippet = computed(() => `<script setup lang="ts">\nimport { ref } from 'vue'\nimport { NoratoSidebar, type NoratoSidebarSection } from '@norato/vue'\nconst collapsed = ref(false)\nconst activeHref = ref('/overview')\nconst sections: NoratoSidebarSection[] = ${JSON.stringify([{label:'فضای کاری',items:[{label:'نمای کلی',href:'/overview',icon:'⌂'},{label:'پروژه‌ها',href:'/projects',icon:'▦',count:3},{label:'تنظیمات',href:'/settings',icon:'⚙'}]}],null,2)}\n<\\/script>\n<template><NoratoSidebar id="workspace-nav" v-model:collapsed="collapsed" :sections="sections" :active-href="activeHref" @navigate="item => activeHref = item.href || activeHref" /></template>`)
</script>
<template><div class="button-playground sidebar-playground" dir="rtl"><header><strong>آزمایش Sidebar اجرایی</strong><span>گروه، پیوند، جمع‌شدن، حالت موبایل و غیرفعال را بررسی کن.</span></header><div class="button-playground-preview sidebar-playground-preview"><NoratoSidebar id="sidebar-playground" v-model:collapsed="collapsed" :sections="sections" :active-href="activeHref" :disabled="disabled" :variant="variant" @navigate="item => { activeHref = item.href || activeHref; activations++ }"/><p role="status" aria-live="polite">{{ activations ? `انتخاب: ${activeHref}` : 'وضعیت تعامل اینجا نمایش داده می‌شود.' }}</p></div><div class="button-playground-controls"><PlaygroundSelect id="sidebar-variant" v-model="variant" label="سبک" :options="[{value:'glass',label:'Glass'},{value:'bar',label:'Bar'}]"/><label class="button-playground-switch"><input v-model="collapsed" type="checkbox"/><span class="button-playground-track" aria-hidden="true"><span/></span><span>جمع‌شده</span></label><label class="button-playground-switch"><input v-model="disabled" type="checkbox"/><span class="button-playground-track" aria-hidden="true"><span/></span><span>غیرفعال</span></label></div><div class="button-playground-code"><div class="button-playground-codebar"><strong>کد Vue</strong><button class="copy-section-button" type="button" @click="emit('copy','sidebar-playground',snippet)">{{ props.copiedKey==='sidebar-playground'?'کپی شد':'کپی کد' }}</button></div><pre class="usage-code" dir="ltr"><code>{{ snippet }}</code></pre></div></div></template>
<style>.sidebar-playground-preview{display:flex;align-items:flex-start;gap:var(--norato-space-4);overflow:auto}.sidebar-playground-preview>p{color:var(--norato-color-text-secondary)}@media(max-width:700px){.sidebar-playground-preview{flex-wrap:wrap}}</style>
